import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.XwxSdVYF.js";const r="/VirtualC64/docs/assets/state.tC6YYRVv.svg",m=JSON.parse('{"title":"State Model","description":"","frontmatter":{"title":"State Model","kind":"page"},"headers":[],"relativePath":"guide/state.md","filePath":"guide/state.md"}'),n={name:"guide/state.md"};function o(l,e,h,d,c,u){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="statemodel" tabindex="-1">State Model <a class="header-anchor" href="#statemodel" aria-label="Permalink to &quot;State Model {#statemodel}&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>After calling <a href="/VirtualC64/docs/api/vc64-VirtualC64#launch">launch()</a>, the emulator runs as a single thread alongside the front-end. The thread lives as long as the emulator object, but it does not compute frames all the time. What it does is controlled by its execution state (<a href="/VirtualC64/docs/api/enum-ExecState">vc64::ExecState</a>).</p><ul><li><strong>Off:</strong> The emulator is powered off.</li><li><strong>Paused:</strong> The emulator is powered on, but no frames are computed.</li><li><strong>Running:</strong> The emulator is powered on and computes frames.</li><li><strong>Halted:</strong> The emulator is in the middle of shutting down.</li></ul><p>A state change is requested with the functions shown in the diagram. Like all state-changing functions, they come in a blocking and an asynchronous flavor (for example <a href="/VirtualC64/docs/api/vc64-VirtualC64#run">run()</a> and <a href="/VirtualC64/docs/api/vc64-VirtualC64#runasync">runAsync()</a>).</p><p><img src="'+r+`" alt=""></p><p>The functions <a href="/VirtualC64/docs/api/vc64-VirtualC64#ispoweredoff">isPoweredOff()</a>, <a href="/VirtualC64/docs/api/vc64-VirtualC64#ispaused">isPaused()</a>, <a href="/VirtualC64/docs/api/vc64-VirtualC64#isrunning">isRunning()</a>, and <a href="/VirtualC64/docs/api/vc64-VirtualC64#ispoweredon">isPoweredOn()</a> query the state. Running an emulator that is powered off switches it on first. If a required ROM is missing, <a href="/VirtualC64/docs/api/vc64-VirtualC64#run">run()</a> throws a <a href="/VirtualC64/docs/api/vc64-CoreError#coreerror">CoreError</a>. <a href="/VirtualC64/docs/api/vc64-VirtualC64#checkready">checkReady()</a> performs the same check without running the emulator.</p><h2 id="suspension" tabindex="-1">Suspension <a class="header-anchor" href="#suspension" aria-label="Permalink to &quot;Suspension&quot;">​</a></h2><p>Independent of the execution state, the emulator thread can be <em>suspended</em> for a short period of time with <a href="/VirtualC64/docs/api/vc64-API#suspend">suspend()</a>. A suspended thread stops at a safe point (it is neither computing a frame nor carrying out commands) and continues once <a href="/VirtualC64/docs/api/vc64-API#resume">resume()</a> has been called. The execution state does not change. <a href="/VirtualC64/docs/api/vc64-VirtualC64#issuspended">isSuspended()</a> reports whether a suspension is active.</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#C0CAF5;">c64</span><span style="--shiki-light:#24292E;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#7AA2F7;">suspend</span><span style="--shiki-light:#24292E;--shiki-dark:#9ABDF5;">()</span><span style="--shiki-light:#24292E;--shiki-dark:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#51597D;--shiki-dark-font-style:italic;">// Read the state of the components consistently</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#C0CAF5;">c64</span><span style="--shiki-light:#24292E;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#7AA2F7;">resume</span><span style="--shiki-light:#24292E;--shiki-dark:#9ABDF5;">()</span><span style="--shiki-light:#24292E;--shiki-dark:#89DDFF;">;</span></span></code></pre></div><p>Suspensions can be nested. Each <a href="/VirtualC64/docs/api/vc64-API#suspend">suspend()</a> must be followed by exactly one <a href="/VirtualC64/docs/api/vc64-API#resume">resume()</a>, so the code in between must not be left by an exception. Only one thread can hold a suspension at a time; others wait until it is released. The holder must not call a blocking API function, because the emulator thread cannot carry out the request. Such a call throws a <a href="/VirtualC64/docs/api/vc64-CoreError#coreerror">CoreError</a> instead of deadlocking. Use the asynchronous flavors instead.</p><h2 id="synchronization" tabindex="-1">Synchronization <a class="header-anchor" href="#synchronization" aria-label="Permalink to &quot;Synchronization&quot;">​</a></h2><p>The emulator thread does not run freely. To compute the proper number of frames per second, it waits for an external wake-up signal and then computes all frames that are missing. The front-end sends the signal by calling <a href="/VirtualC64/docs/api/vc64-VirtualC64#wakeup">wakeUp()</a>. The best moment is right after the current texture has been handed over to the GPU, which usually coincides with a VSYNC pulse. If the thread falls too far behind, it resynchronizes itself instead of trying to catch up.</p><h2 id="warp-mode" tabindex="-1">Warp mode <a class="header-anchor" href="#warp-mode" aria-label="Permalink to &quot;Warp mode&quot;">​</a></h2><p>To speed up emulation (e.g., during disk accesses), the emulator can be put into <em>warp mode</em>. In this mode, timing synchronization is disabled and the emulator runs as fast as possible. Several clients can request warp mode independently by using different sources (see <a href="/VirtualC64/docs/api/vc64-VirtualC64#warpon">warpOn()</a>). The mode stays on as long as at least one source has requested it. The option <a href="/VirtualC64/docs/api/enum-Opt">C64_WARP_MODE</a> selects when warp mode is entered automatically.</p><h2 id="track-mode" tabindex="-1">Track mode <a class="header-anchor" href="#track-mode" aria-label="Permalink to &quot;Track mode&quot;">​</a></h2><p>Similar to warp mode, the emulator can be put into <em>track mode</em> (see <a href="/VirtualC64/docs/api/vc64-VirtualC64#trackon">trackOn()</a>). A GUI enables it while its debugger is open. In track mode, several time-consuming tasks are performed that are usually left out. For example, the CPU records all executed instructions in a trace buffer.</p>`,17)])])}const f=a(n,[["render",o]]);export{m as __pageData,f as default};
